DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.finance_installment_page(date,text,text,integer,integer)'::regprocedure) INTO d; IF position('''id'',r.id,''guest_name'',r.guest_name' IN d)=0 THEN RAISE EXCEPTION 'finance projection missing'; END IF; d:=replace(d,'''id'',r.id,''guest_name'',r.guest_name','''id'',r.id,''room_id'',r.room_id,''guest_name'',r.guest_name'); EXECUTE d; END $$;